        [Test] public void BodyQueryPhasesColdNextCowReadyAndMalformedCursor()=>BodyActualSolverPhasesColdBytesNextCowReadyForkAndEveryNth("partition-query");
        [TestCase("direct")][TestCase("singleton")][TestCase("field-packed")][TestCase("field-tree")][TestCase("shared")][TestCase("layered-singleton")][TestCase("layered-shared")][TestCase("partition-singleton")][TestCase("partition-shared")]
        public void BodyActualSolverPhasesColdBytesNextCowReadyForkAndEveryNth(string kind)
        {
            bool isField=kind.StartsWith("field"),isShared=kind.EndsWith("shared");
            NavSolveStatus Status(NavOwnedStorage w)=>w is NavSharedTerminalField f?f.Status:w is NavIncrementalSingletonRoute s?s.Status:((NavIncrementalSharedRoute)w).Status;
            int Advance(NavOwnedStorage w)=>(w is NavSharedTerminalField f?f.Advance(1):w is NavIncrementalSingletonRoute s?s.Advance(1):((NavIncrementalSharedRoute)w).Advance(1)).Consumed;
            void Seal(NavOwnedStorage w){if(w is NavSharedTerminalField f)f.SealPrepared();else if(w is NavIncrementalSingletonRoute s)s.SealPrepared();else((NavIncrementalSharedRoute)w).SealPrepared();}
            object Phase(NavOwnedStorage w)=>w.GetType().GetField("phase",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(w);
            NavRetainedArray<NavOwnedStorage> Source(NavigationRetentionBudget budget,int steps){
                Assert.True(budget.TryOpenScope(NavigationPreparationKind.Reconstruction,1,1,out var initial));var reserve=initial.OwnedReservation();
                ILayeredNavigationProvider provider=kind.StartsWith("partition")?new PartitionNavigationProvider(ThreeCrossingsMap.Default,new NavGeometry(ThreeCrossingsMap.Default.HalfExtent,ThreeCrossingsMap.Default.MovementBlockers.ToArray(),ThreeCrossingsMap.Default.Revision),null):kind.StartsWith("layered")?(ILayeredNavigationProvider)new StackedNavigationFixture().Provider:NavigationAdmission.CertifiedFlatProvider(new NavGeometry(3,kind=="direct"?Array.Empty<NavObstacle>():new[]{new NavObstacle(-.5,-.5,.5,.5)},1));
                var compiler=LayeredNavigationCompileWork.CopyProviderAndCreateOwned(provider,new NavClearanceProfile("ground",1,"ground",1,.25),new NavGraphProfile(new string('b',64),"distance",1,kind.StartsWith("partition")?16:kind.StartsWith("layered")?8:1),new NavGraphCompileLimits(2000,2000,10000),reserve);int compileSteps=0;while(compiler.Phase!=LayeredNavigationCompileWork.Stage.Ready){Assert.Less(++compileSteps,20000);compiler.Advance(1);}compiler.SealPrepared();var graph=compiler.Graph;
                var origin=new NavLocation(new NavPoint(-2,0),NavLocation.FlatSurface);var endpoint=new NavLocation(new NavPoint(2,0),NavLocation.FlatSurface);if(kind.StartsWith("layered")){origin=StackedNavigationFixture.Entry;endpoint=StackedNavigationFixture.Exit;}else if(kind.StartsWith("partition")){origin=graph.Nodes[0].Location;endpoint=graph.Nodes[graph.Nodes.Count-1].Location;}var sub=new NavRouteSubscription(1,1,1,1,0,1,1,1,1,1,1,origin,endpoint,null);
                NavSharedTerminalField field=null;if(isField||isShared){field=NavSharedTerminalField.CopyRegionAndCreateOwned(graph,new NavTerminalRegion("body-field",1,endpoint,new[]{endpoint}),4096,reserve,kind=="field-tree");if(isShared){int n=0;while(field.Status==NavSolveStatus.Pending){Assert.Less(++n,20000);field.Advance(1);}Assert.AreEqual(NavSolveStatus.Ready,field.Status);field.SealPrepared();}}
                NavTerminalRegion query=null;if(kind=="partition-query"){
                    var alternative=new[]{new NavPoint(-.125,0),new NavPoint(.125,0),new NavPoint(0,-.125),new NavPoint(0,.125)}.Select(d=>new NavLocation(new NavPoint(endpoint.Position.X+d.X,endpoint.Position.Z+d.Z),endpoint.SurfaceId)).First(at=>graph.IsValid(at)&&graph.CanSweep(at,endpoint));
                    query=new NavTerminalRegion("body-query",1,endpoint,new[]{endpoint,alternative});
                }
                NavOwnedStorage work=isField?(NavOwnedStorage)field:isShared?(NavOwnedStorage)NavIncrementalSharedRoute.CopySubscriptionAndCreateOwned(field,sub,reserve):NavIncrementalSingletonRoute.CopySubscriptionAndCreateOwned(graph,sub,4096,reserve,query);
                for(int n=0;n<steps;n++)Advance(work);Seal(work);var route=work is NavIncrementalSingletonRoute s?s.Route:work is NavIncrementalSharedRoute shared?shared.Route:null;
                var bundle=NavRetainedArray<NavOwnedStorage>.Copy(new NavOwnedStorage[]{work,work,graph,field,route},initial.TryReserve);work.ReleaseOwner();if(field!=null&&!isField)field.ReleaseStorage();compiler.ReleaseStorage();initial.Attach(bundle);initial.Commit(bundle,_=>{});Assert.AreEqual(Unique(bundle),budget.PhysicalBytes);return bundle;
            }
            var discoveryBudget=new NavigationRetentionBudget();var discovery=Source(discoveryBudget,0);
            if(kind=="partition-query"){
                var work=discovery[0];var phaseField=work.GetType().GetField("phase",BindingFlags.Instance|BindingFlags.NonPublic);var cursorField=work.GetType().GetField("cursor",BindingFlags.Instance|BindingFlags.NonPublic);
                var originalPhase=phaseField.GetValue(work);var originalCursor=cursorField.GetValue(work);
                phaseField.SetValue(work,Enum.Parse(originalPhase.GetType(),"QueryValidate"));cursorField.SetValue(work,3);
                byte[] malformed=CaptureGraph(discoveryBudget,discovery);phaseField.SetValue(work,originalPhase);cursorField.SetValue(work,originalCursor);
                var rejectedBudget=new NavigationRetentionBudget();Assert.True(rejectedBudget.TryOpenScope(NavigationPreparationKind.Decode,1,99,out var rejected));
                Assert.Throws<ArgumentException>(()=>Decode(malformed,rejected.OwnedReservation()),"reject phase-specific candidate cursor before publication");rejected.Discard();Assert.Zero(rejectedBudget.PhysicalBytes);Assert.Zero(rejectedBudget.HeldBytes);Assert.Zero(rejectedBudget.ActiveScopes);
            }
            var boundaries=new SortedSet<int>{0,1};int total=0,partialTraceSnapshots=0;
            Assert.True(discoveryBudget.TryOpenScope(NavigationPreparationKind.Projection,1,3,out var discoverScope));var discovered=Fork(discovery[0],discoverScope.OwnedReservation());object phase=Phase(discovered);while(Status(discovered)==NavSolveStatus.Pending){Assert.Less(++total,20000);Advance(discovered);int traceCursor=discovered is NavIncrementalSingletonRoute?(int)typeof(NavIncrementalSingletonRoute).GetField("reconstructLeg",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(discovered):discovered is NavIncrementalSharedRoute?(int)typeof(NavIncrementalSharedRoute).GetField("arcLeg",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(discovered):0;if(traceCursor>0){boundaries.Add(total);partialTraceSnapshots++;}if(!phase.Equals(Phase(discovered))){boundaries.Add(total-1);boundaries.Add(total);boundaries.Add(total+1);phase=Phase(discovered);}}Assert.AreEqual(NavSolveStatus.Ready,Status(discovered));if(kind.StartsWith("partition"))Assert.Greater(partialTraceSnapshots,0,"actual partition partial trace must be witnessed");Seal(discovered);discoverScope.Attach(discovered);discoverScope.Discard();discovery.Release();Assert.Zero(discoveryBudget.PhysicalBytes);Assert.Zero(discoveryBudget.HeldBytes);boundaries.Add(total);
            NavOwnedStorage Fork(NavOwnedStorage w,INavStorageReservation r)=>w is NavSharedTerminalField f?(NavOwnedStorage)f.ForkOwned(r):w is NavIncrementalSingletonRoute s?(NavOwnedStorage)s.ForkOwned(r):((NavIncrementalSharedRoute)w).ForkOwned((NavSharedTerminalField)typeof(NavIncrementalSharedRoute).GetField("field",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(w),r);
            byte[] Next(NavigationRetentionBudget budget,NavOwnedStorage work,out long charge,out int used){Assert.True(budget.TryOpenScope(NavigationPreparationKind.Projection,1,10,out var scope));var fork=Fork(work,scope.OwnedReservation());used=Advance(fork);Seal(fork);scope.Attach(fork);scope.Commit(fork,_=>{});var result=CaptureGraph(budget,fork,11);charge=Unique(fork);fork.ReleaseOwner();return result;}
            foreach(int at in boundaries){if(at>total)continue;var hot=new NavigationRetentionBudget();var bundle=Source(hot,at);var bytes=CaptureGraph(hot,bundle);long charge=hot.PhysicalBytes;var next=Next(hot,bundle[0],out long nextCharge,out int used);CollectionAssert.AreEqual(bytes,CaptureGraph(hot,bundle,12));Assert.AreEqual(charge,hot.PhysicalBytes);bundle.Release();bundle=null;Assert.Zero(hot.PhysicalBytes);Assert.Zero(hot.HeldBytes);
                var cold=new NavigationRetentionBudget();Assert.True(cold.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var decode));var restored=(NavRetainedArray<NavOwnedStorage>)Decode(bytes,decode.OwnedReservation());decode.Attach(restored);decode.Commit(restored,_=>{});Assert.AreSame(restored[0],restored[1]);Assert.AreEqual(charge,cold.PhysicalBytes);Assert.AreEqual(Unique(restored),cold.PhysicalBytes);CollectionAssert.AreEqual(bytes,CaptureGraph(cold,restored));CollectionAssert.AreEqual(next,Next(cold,restored[0],out long actualCharge,out int actualUsed),kind+" next "+at);Assert.AreEqual(nextCharge,actualCharge);Assert.AreEqual(used,actualUsed);restored.Release();restored=null;Assert.Zero(cold.PhysicalBytes);Assert.Zero(cold.HeldBytes);
                if(at==total){var forkBudget=new NavigationRetentionBudget();Assert.True(forkBudget.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var fd));var readyFork=Decode(next,fd.OwnedReservation());fd.Attach(readyFork);fd.Commit(readyFork,_=>{});CollectionAssert.AreEqual(next,CaptureGraph(forkBudget,readyFork));Assert.AreEqual(nextCharge,forkBudget.PhysicalBytes);readyFork.ReleaseOwner();Assert.Zero(forkBudget.PhysicalBytes);Assert.Zero(forkBudget.HeldBytes);
                    var countBudget=new NavigationRetentionBudget();Assert.True(countBudget.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var cs));var counter=new Refusal(cs,int.MaxValue);var trial=Decode(bytes,counter);cs.Attach(trial);int allocations=counter.Calls;cs.Discard();Assert.Zero(countBudget.PhysicalBytes);Assert.Zero(countBudget.HeldBytes);
                    for(int nth=1;nth<=allocations;nth++){var rejectedBudget=new NavigationRetentionBudget();Assert.True(rejectedBudget.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var rs));var refusing=new Refusal(rs,nth);Assert.Throws<InvalidOperationException>(()=>Decode(bytes,refusing),kind+" refusal "+nth);Assert.AreEqual(nth,refusing.Calls);rs.Discard();Assert.Zero(rejectedBudget.PhysicalBytes);Assert.Zero(rejectedBudget.HeldBytes);}
                }
            }
        }
        [TestCase(true,null)][TestCase(false,null)][TestCase(true,"")][TestCase(false,"")][TestCase(true,"hold")][TestCase(false,"hold")]
        public void BodyStandaloneSubscriptionExactAliasesHoldColdRefusalAndCanonicalBooleans(bool shared,string hold)
        {
            string from=new string("flat".ToCharArray()),to=shared?from:new string("flat".ToCharArray());var source=new NavRouteSubscription(1,1,1,1,0,1,1,1,1,1,1,new NavLocation(new NavPoint(-1,0),from),new NavLocation(new NavPoint(1,0),to),hold);
            var hot=new NavigationRetentionBudget();Assert.True(hot.TryOpenScope(NavigationPreparationKind.Admission,1,1,out var initial));var copied=NavRouteSubscription.CopyOwned(source,initial.OwnedReservation());var root=copied.MetadataOwner;Assert.AreNotSame(source,copied);Assert.AreNotSame(from,copied.Origin.SurfaceId);Assert.AreEqual(shared,ReferenceEquals(copied.Origin.SurfaceId,copied.AssignedEndpoint.SurfaceId));initial.Attach(root);initial.Commit(root,_=>{});var bytes=CaptureGraph(hot,root);long charge=hot.PhysicalBytes;root.Release();root=null;copied=null;source=null;Assert.Zero(hot.PhysicalBytes);Assert.Zero(hot.HeldBytes);
            var cold=new NavigationRetentionBudget();Assert.True(cold.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var decode));var restored=(NavDeclarationStorage)Decode(bytes,decode.OwnedReservation());decode.Attach(restored);decode.Commit(restored,_=>{});var value=(NavRouteSubscription)restored.Facade;Assert.AreEqual(shared,ReferenceEquals(value.Origin.SurfaceId,value.AssignedEndpoint.SurfaceId));Assert.AreEqual(hold,value.HoldBinding);Assert.AreEqual(charge,cold.PhysicalBytes);CollectionAssert.AreEqual(bytes,CaptureGraph(cold,restored));
            var foreign=new NavigationRetentionBudget();Assert.True(foreign.TryOpenScope(NavigationPreparationKind.Admission,1,1,out var fs));var foreignRefusal=new Refusal(fs,int.MaxValue);Assert.Throws<ArgumentException>(()=>NavRouteSubscription.CopyOwned(value,foreignRefusal));Assert.Zero(foreignRefusal.Calls);fs.Discard();Assert.Zero(foreign.PhysicalBytes);Assert.Zero(foreign.HeldBytes);restored.Release();value=null;restored=null;Assert.Zero(cold.PhysicalBytes);Assert.Zero(cold.HeldBytes);
            foreach(int offset in new[]{21,shared?22:26}){var malformed=(byte[])bytes.Clone();malformed[offset]=2;var bad=new NavigationRetentionBudget();Assert.True(bad.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var rejected));Assert.Throws<ArgumentException>(()=>Decode(malformed,rejected.OwnedReservation()));rejected.Discard();Assert.Zero(bad.PhysicalBytes);Assert.Zero(bad.HeldBytes);}
            var countBudget=new NavigationRetentionBudget();Assert.True(countBudget.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var cs));var counter=new Refusal(cs,int.MaxValue);var trial=Decode(bytes,counter);cs.Attach(trial);int total=counter.Calls;cs.Discard();Assert.Zero(countBudget.PhysicalBytes);Assert.Zero(countBudget.HeldBytes);
            for(int nth=1;nth<=total;nth++){var rejectedBudget=new NavigationRetentionBudget();Assert.True(rejectedBudget.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var rs));var refusing=new Refusal(rs,nth);Assert.Throws<InvalidOperationException>(()=>Decode(bytes,refusing));Assert.AreEqual(nth,refusing.Calls);rs.Discard();Assert.Zero(rejectedBudget.PhysicalBytes);Assert.Zero(rejectedBudget.HeldBytes);}
        }
        [TestCase("singleton-root")][TestCase("field-root")][TestCase("field-cycle")][TestCase("direct-cost")][TestCase("shared-cost")][TestCase("singleton-bool")][TestCase("field-bool")]
        public void BodySolverMalformedRootsCyclesBoundaryCostsAndBooleansFailClosed(string kind)
        {
            var flags=BindingFlags.Instance|BindingFlags.NonPublic;
            object Get(object value,string name)=>value.GetType().GetField(name,flags).GetValue(value);
            void Set(object value,string name,object data)=>value.GetType().GetField(name,flags).SetValue(value,data);
            var hot=new NavigationRetentionBudget();Assert.True(hot.TryOpenScope(NavigationPreparationKind.Reconstruction,1,1,out var scope));var reservation=scope.OwnedReservation();
            ILayeredNavigationProvider provider=kind=="field-cycle"?(ILayeredNavigationProvider)new StackedNavigationFixture().Provider:NavigationAdmission.CertifiedFlatProvider(new NavGeometry(3,kind=="direct-cost"?Array.Empty<NavObstacle>():new[]{new NavObstacle(-.5,-.5,.5,.5)},1));
            var compiler=LayeredNavigationCompileWork.CopyProviderAndCreateOwned(provider,new NavClearanceProfile("ground",1,"ground",1,.25),new NavGraphProfile(new string('e',64),"distance",1,kind=="field-cycle"?2:1),new NavGraphCompileLimits(2000,2000,10000),reservation);int steps=0;while(compiler.Phase!=LayeredNavigationCompileWork.Stage.Ready){Assert.Less(++steps,20000);compiler.Advance(1);}compiler.SealPrepared();var graph=compiler.Graph;
            var origin=new NavLocation(new NavPoint(-2,0),NavLocation.FlatSurface);var endpoint=new NavLocation(new NavPoint(2,0),NavLocation.FlatSurface);NavGraphArc zero=default,reverse=default;
            if(kind=="field-cycle"){zero=graph.Arcs.First(a=>a.Cost==0&&a.From!=a.To);reverse=graph.Outgoing(zero.To).First(a=>a.To==zero.From&&a.Cost==0);origin=endpoint=graph.Nodes[zero.From].Location;}
            var sub=new NavRouteSubscription(1,1,1,1,0,1,1,1,1,1,1,origin,endpoint,null);bool fieldCase=kind.StartsWith("field"),sharedCase=kind=="shared-cost";NavSharedTerminalField field=null;
            if(fieldCase||sharedCase){field=NavSharedTerminalField.CopyRegionAndCreateOwned(graph,new NavTerminalRegion("malformed",1,endpoint,new[]{endpoint}),4096,reservation,true);if(kind!="field-root"){steps=0;while(field.Status==NavSolveStatus.Pending){Assert.Less(++steps,20000);field.Advance(1);}}}
            NavOwnedStorage work=fieldCase?(NavOwnedStorage)field:sharedCase?(NavOwnedStorage)NavIncrementalSharedRoute.CopySubscriptionAndCreateOwned(field,sub,reservation):NavIncrementalSingletonRoute.CopySubscriptionAndCreateOwned(graph,sub,4096,reservation);
            NavSolveStatus Status()=>fieldCase?field.Status:sharedCase?((NavIncrementalSharedRoute)work).Status:((NavIncrementalSingletonRoute)work).Status;
            void Advance(){if(fieldCase)field.Advance(1);else if(sharedCase)((NavIncrementalSharedRoute)work).Advance(1);else((NavIncrementalSingletonRoute)work).Advance(1);}
            if(kind.EndsWith("root")){steps=0;while((fieldCase?((NavCowDictionary<long,double>)Get(work,"distance")).Count:((NavCowDictionary<int,double>)Get(work,"distance")).Count)==0){Assert.Less(++steps,20000);Advance();}
                if(fieldCase){var distances=(NavCowDictionary<long,double>)Get(work,"distance");var root=distances.First();distances[root.Key]=root.Value+1;var frontier=(NavFieldFrontier)Get(work,"frontier");frontier.Remove(new NavQueueEntry{Node=(int)root.Key,Candidate=0,Cost=root.Value});frontier.Add(new NavQueueEntry{Node=(int)root.Key,Candidate=0,Cost=root.Value+1});}
                else {var distances=(NavCowDictionary<int,double>)Get(work,"distance");var root=distances.First();distances[root.Key]=root.Value+1;var frontier=(NavCowOrderedSet<NavQueueEntry>)Get(work,"frontier");frontier.Remove(new NavQueueEntry{Node=root.Key,Candidate=0,Cost=root.Value});frontier.Add(new NavQueueEntry{Node=root.Key,Candidate=0,Cost=root.Value+1});}
            }else {steps=0;while(Status()==NavSolveStatus.Pending){Assert.Less(++steps,20000);Advance();}Assert.AreEqual(NavSolveStatus.Ready,Status());}
            if(kind=="field-cycle"){var next=(NavCowDictionary<long,NavGraphArc>)Get(field,"next");next[zero.From]=zero;next[zero.To]=reverse;var distance=(NavCowDictionary<long,double>)Get(field,"distance");Assert.Zero(distance[zero.From]);Assert.Zero(distance[zero.To]);}
            if(kind.EndsWith("cost")){var route=sharedCase?((NavIncrementalSharedRoute)work).Route:((NavIncrementalSingletonRoute)work).Route;Set(route.Legs[0],"<Cost>k__BackingField",route.Legs[0].Cost+1);double sum=0;foreach(var leg in route.Legs)sum+=leg.Cost;Set(route,"<Cost>k__BackingField",sum);if(sharedCase)Set(work,"routeCost",sum);}
            if(fieldCase)field.SealPrepared();else if(sharedCase){field.SealPrepared();((NavIncrementalSharedRoute)work).SealPrepared();}else((NavIncrementalSingletonRoute)work).SealPrepared();scope.Attach(work);scope.Commit(work,_=>{});var bytes=CaptureGraph(hot,work);long charge=hot.PhysicalBytes;
            if(kind.EndsWith("bool"))bytes[kind=="field-bool"?49:73]=2;
            var cold=new NavigationRetentionBudget();Assert.True(cold.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var rejected));Assert.Throws<ArgumentException>(()=>Decode(bytes,rejected.OwnedReservation()));rejected.Discard();Assert.Zero(cold.PhysicalBytes);Assert.Zero(cold.HeldBytes);Assert.AreEqual(charge,hot.PhysicalBytes);work.ReleaseOwner();if(sharedCase)field.ReleaseStorage();compiler.ReleaseStorage();Assert.Zero(hot.PhysicalBytes);Assert.Zero(hot.HeldBytes);
        }
        [TestCase(false)][TestCase(true)]
        public void BodyZeroNodeFieldColdBytesNextCowPreserveUninspectedCandidate(bool tree)
        {
            for(int at=0;at<=4;at++){
                var hot=new NavigationRetentionBudget();Assert.True(hot.TryOpenScope(NavigationPreparationKind.Reconstruction,1,1,out var scope));var r=scope.OwnedReservation();var provider=NavigationAdmission.CertifiedFlatProvider(new NavGeometry(.6,new[]{new NavObstacle(-.1,-.1,.1,.1)},1));
                var compiler=LayeredNavigationCompileWork.CopyProviderAndCreateOwned(provider,new NavClearanceProfile("ground",1,"ground",1,.05),new NavGraphProfile(new string('a',64),"distance",1,2),new NavGraphCompileLimits(2000,2000,10000),r);int steps=0;while(compiler.Phase!=LayeredNavigationCompileWork.Stage.Ready){Assert.Less(++steps,20000);compiler.Advance(1);}compiler.SealPrepared();Assert.Zero(compiler.Graph.Nodes.Count);var goal=new NavLocation(new NavPoint(.4,0),NavLocation.FlatSurface);
                var field=NavSharedTerminalField.CopyRegionAndCreateOwned(compiler.Graph,new NavTerminalRegion("zero-node",1,goal,new[]{goal}),4096,r,tree);for(int n=0;n<at;n++)field.Advance(1);field.SealPrepared();compiler.ReleaseStorage();scope.Attach(field);scope.Commit(field,_=>{});var bytes=CaptureGraph(hot,field);long charge=hot.PhysicalBytes;
                byte[] Next(NavigationRetentionBudget b,NavSharedTerminalField f,out int consumed){Assert.True(b.TryOpenScope(NavigationPreparationKind.Projection,1,10,out var projection));var fork=f.ForkOwned(projection.OwnedReservation());consumed=fork.Advance(1).Consumed;fork.SealPrepared();projection.Attach(fork);projection.Commit(fork,_=>{});var result=CaptureGraph(b,fork);fork.ReleaseStorage();return result;}
                var expected=Next(hot,field,out int used);field.ReleaseStorage();field=null;Assert.Zero(hot.PhysicalBytes);Assert.Zero(hot.HeldBytes);
                var cold=new NavigationRetentionBudget();Assert.True(cold.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var decode));var restored=(NavSharedTerminalField)Decode(bytes,decode.OwnedReservation());decode.Attach(restored);decode.Commit(restored,_=>{});Assert.AreEqual(charge,cold.PhysicalBytes);CollectionAssert.AreEqual(bytes,CaptureGraph(cold,restored));CollectionAssert.AreEqual(expected,Next(cold,restored,out int actual));Assert.AreEqual(used,actual);restored.ReleaseStorage();Assert.Zero(cold.PhysicalBytes);Assert.Zero(cold.HeldBytes);
            }
        }
